insert into public.quiz_banks (pathway, level_min, level_max, youth_stage, quarter, questions) values
  ('ntrp', 3.5, 3.5, null, 1, '[{"q": "You''re rallying cross-court from the baseline and your opponent hits a medium-paced ball to your forehand, above the net by about 2 feet. What''s the smart shot?", "options": ["Go for a winner down the line", "Hit a solid cross-court shot with margin over the net", "Slice it short into the net", "Try a drop shot"], "correct": 1, "explain": "At a 3.5 level, the neutral rally ball should be your default, not just an option — hitting cross-court with margin (on both wings, not just your favorite side) keeps you in the point and makes the opponent hit one more ball."}, {"q": "Where is the safest target on a cross-court rally ball?", "options": ["As close to the sideline as possible", "Deep, toward the middle of the opponent''s cross-court zone", "Right at the opponent''s feet", "Down the middle of the whole court, ignoring cross-court"], "correct": 1, "explain": "Deep and toward the middle of the cross-court zone gives the biggest margin for error while still pushing the opponent back."}, {"q": "On your first serve, you keep double-faulting because you''re going for too much power. What should you do?", "options": ["Serve even harder to make up for it", "Take some pace off and focus on a consistent target", "Only ever hit second serves", "Aim for the net"], "correct": 1, "explain": "A 3.5-level player builds free points from a serve that''s IN — spin and placement beat raw power at this stage."}, {"q": "Where should you aim most of your return of serve when just starting to build 3.5-level consistency?", "options": ["Down the line at the server''s feet", "Deep, toward the middle of the court", "Short and angled crosscourt", "Right back at the server as hard as possible"], "correct": 1, "explain": "A deep, middle return is the highest-percentage choice at 3.5 — it limits the server''s angles, gives you time to recover, and works off either wing, not just your stronger side."}, {"q": "You just missed an easy shot into the net on a big point. What should you do between points?", "options": ["Get angry and rush the next point to make up for it", "Use your breathe–bounce–set routine and reset", "Change your entire strategy", "Think about the mistake while walking to the line"], "correct": 1, "explain": "A consistent between-point routine (breathe, bounce the ball, set your focus) helps you let go of the last point and play the next one fresh."}, {"q": "During a rally, which shot generally gives a 3.5-level player the most time to recover to the middle of the court?", "options": ["A flat, low shot down the line", "A shot with topspin and net clearance, hit with rhythm", "A rushed slap at the ball", "A shot hit while still moving sideways at full speed"], "correct": 1, "explain": "A balanced, rhythmic shot with good net clearance buys you time to split-step and recover, unlike rushed or off-balance shots."}, {"q": "Your opponent hits a short ball that lands near the service line. What''s your first read?", "options": ["Stay back and rally like normal", "Recognize it as an opportunity to move forward", "Hit a defensive slice", "Run around it to hit a forehand from way behind the baseline"], "correct": 1, "explain": "Recognizing short balls early is the foundation of attacking tennis — the first step is simply noticing the opportunity to move in."}, {"q": "What''s the main goal of your footwork split-step?", "options": ["To look athletic", "To be ready to move explosively as soon as you read your opponent''s shot", "To slow yourself down before hitting", "It''s only needed at the net"], "correct": 1, "explain": "The split-step, timed as the opponent contacts the ball, loads your legs so you can react quickly in any direction."}, {"q": "You''re serving at 30-30 (a somewhat important point). What''s the best mindset?", "options": ["Panic and rush", "Use your normal pre-serve routine and go for your usual reliable target", "Try a brand new serve you''ve never practiced", "Stall as long as possible"], "correct": 1, "explain": "Big points are won by sticking to routines and reliable patterns you''ve trained — not by suddenly trying something new."}, {"q": "In a cross-court rally, why do coaches call the deep cross-court shot the ''safest'' shot in tennis?", "options": ["Because the net is lower in the middle", "Because the court is longer diagonally, giving more margin over the net and inside the lines", "Because opponents can''t reach cross-court balls", "It isn''t actually safer — that''s a myth"], "correct": 1, "explain": "The diagonal (cross-court) distance is the longest line on the court, which means more room over the net and more room inside the sideline."}]'::jsonb),
  ('ntrp', 3.5, 3.5, null, 2, '[{"q": "You''re stuck in a rally trading flat, fast shots and starting to lose control. What can help you reset?", "options": ["Hit even flatter and harder", "Add more topspin and net clearance to slow the pace and buy time", "Stop moving your feet", "Try to end the point immediately with a risky shot"], "correct": 1, "explain": "A 3.5 player uses shape (topspin, more net clearance) on both forehand and backhand to slow the rally down, buy time, and lower the error rate — not just on one preferred wing."}, {"q": "Your opponent hits a short ball. You move forward and hit a good approach shot. What should you do next?", "options": ["Stay at the baseline and wait", "Follow your approach shot toward the net, ready to volley", "Run to the opposite corner", "Turn your back to the net"], "correct": 1, "explain": "An approach shot is only half the plan — closing toward the net afterward lets you finish the point with a volley."}, {"q": "Where should a good approach shot usually be aimed?", "options": ["Short and in the middle of the court", "Deep, and generally toward the side you''re NOT approaching down (or deep middle)", "Straight at the opponent", "Out wide no matter what"], "correct": 1, "explain": "A deep approach shot gives your opponent less time and fewer angles to pass you as you move forward."}, {"q": "At the net, a ball comes at you above the net. What''s the priority?", "options": ["A big, looping swing", "A short, punchy volley aimed at open space or deep", "Let it bounce first", "Close your eyes and swing"], "correct": 1, "explain": "Volleys use a short punch, not a full swing — control and placement matter more than power at the net."}, {"q": "In doubles, when your partner is at net and you''re serving, what''s a poach?", "options": ["A type of serve", "Your net partner crossing over to intercept the return", "Calling a let", "A doubles-only version of a lob"], "correct": 1, "explain": "A poach is when the net player moves across to cut off the return, creating pressure and quick points."}, {"q": "Your doubles partner just missed an easy volley and looks upset. What''s the best response?", "options": ["Ignore them completely", "Give quick, positive encouragement and refocus on the next point", "Tell them exactly what they did wrong right away", "Blame them out loud"], "correct": 1, "explain": "Strong doubles teams support each other after errors — quick encouragement keeps both players'' focus on the next point."}, {"q": "When should you generally hit a topspin shot with more shape instead of a flatter, faster one?", "options": ["Never — flat is always better", "When you need more margin, time to recover, or want to move your opponent side to side", "Only on second serves", "Only when you''re already winning"], "correct": 1, "explain": "Shape (topspin, higher net clearance) is a tactical tool for control, recovery time, and moving your opponent — not just a stroke style."}, {"q": "In doubles, where should the serving team''s net player generally stand?", "options": ["On the baseline next to their partner", "Near the service line, close enough to the net to poach", "In the alley the whole time", "Directly behind the server"], "correct": 1, "explain": "Standing near the net (inside the service box area) lets the net player threaten to poach and cover angles."}, {"q": "You hit an approach shot but it landed short and in the middle — a tactical mistake. What''s likely to happen?", "options": ["Nothing — location doesn''t matter", "The opponent gets an easier passing shot or lob because you gave them time and a central target", "You automatically win the point", "It counts as a fault"], "correct": 1, "explain": "A short, central approach gives the opponent both time and angle options — at 3.5, approach shots should reliably go deep and to a side, and be followed to net, not left short and central."}, {"q": "What''s a simple reason to use an overhead (smash) instead of a groundstroke when the ball is lobbed high over you?", "options": ["Overheads are always required by the rules", "It lets you attack the ball with power before it drops and becomes awkward to hit", "It''s more polite", "There''s no real reason"], "correct": 1, "explain": "Taking the ball in the air on a smash lets you finish the point aggressively instead of letting the lob push you back and reset the rally."}]'::jsonb),
  ('ntrp', 3.5, 3.5, null, 3, '[{"q": "What is a ''serve+1'' pattern, a core 3.5-level tactic?", "options": ["Serving twice in a row", "Planning your serve and your very next shot together as a mini-plan", "A doubles rotation rule", "Serving underhand"], "correct": 1, "explain": "Serve+1 means thinking one shot ahead: where you serve, and what you plan to do with the likely return — a hallmark of 3.5-level point construction."}, {"q": "A ball bounces low and short in your service box (a weak, short ball). What category is this?", "options": ["Defend", "Attack", "Neutral", "Ignore it and stay back"], "correct": 1, "explain": "A short, low ball is an attacking opportunity — move in and take time away from your opponent."}, {"q": "You''re pushed way behind the baseline by a deep, heavy shot. What category is this ball, and what should you do?", "options": ["Attack — go for a winner", "Defend — hit a high, deep, safe shot to buy time and recover position", "Neutral — rally normally", "Rush the net immediately"], "correct": 1, "explain": "When you''re out of position or the ball is deep and heavy, the smart play is a defensive shot that buys time, not a risky attempt to attack."}, {"q": "In the defend–neutral–attack framework, what mainly decides which category a ball falls into?", "options": ["The color of the ball", "The ball''s height, depth, and your court position when you contact it", "How tired you feel", "The score"], "correct": 1, "explain": "Reading the ball''s height and depth — plus where your feet are — tells you whether to defend, rally neutrally, or attack."}, {"q": "You''re playing an opponent who mostly pushes the ball back safely and rarely misses (a ''pusher''). What''s the 3.5-level game plan?", "options": ["Try to out-rally them by playing exactly as safely as they do forever", "Be patient, construct points, and look for short balls to attack rather than forcing low-percentage winners", "Only hit drop shots", "Try to hit every ball as hard as possible"], "correct": 1, "explain": "Against a pusher, a 3.5 player stays patient and constructs points — using consistent depth on both wings to work for a short ball to attack, rather than forcing low-percentage winners."}, {"q": "Your opponent hits big, flat, hard shots (a ''hitter''). What''s a smart adjustment?", "options": ["Match their pace shot for shot", "Add more net clearance/shape to slow the ball down and take away their rhythm, and move them side to side", "Stand closer to the baseline than usual", "Give up on footwork"], "correct": 1, "explain": "Against a hard hitter, using more shape and margin (and moving them around) disrupts their rhythm better than matching their pace."}, {"q": "What is ''playing the point before the point''?", "options": ["Practicing before the match", "Having a simple plan for the point before you serve or return", "Warming up extra long", "Talking to your opponent before serving"], "correct": 1, "explain": "Elite juniors form a quick, simple plan (like a serve target or return target) before the point starts, instead of just reacting."}, {"q": "A ball comes to you at a comfortable height near the baseline, and you''re balanced. What category is this?", "options": ["Defend", "Attack only", "Neutral — rally with purpose, look to improve your position", "Ignore the shot"], "correct": 2, "explain": "A comfortable, balanced ball is neutral — a good time to construct the point further rather than force an outcome."}, {"q": "You''re facing an opponent who rushes the net a lot (a ''net-rusher''). What''s a solid tactical response?", "options": ["Hit every shot right at them", "Use passing shots, lobs, and low, dipping returns to make volleys harder", "Stop moving your feet", "Always hit short balls"], "correct": 1, "explain": "Against a net-rusher, low or dipping shots, passing shots, and well-timed lobs make it harder for them to finish points at net."}, {"q": "Why is it useful to have a simple game plan before a match instead of just ''playing and seeing what happens''?", "options": ["Game plans aren''t useful for 10-year-olds", "A plan gives you a way to make decisions under pressure instead of guessing point to point", "It guarantees a win", "It makes the match longer"], "correct": 1, "explain": "A simple plan (patterns to lean on, targets to use) gives you something reliable to fall back on when a match gets tight."}]'::jsonb),
  ('ntrp', 3.5, 3.5, null, 4, '[{"q": "Why mix up serve placement (T, body, wide) instead of always serving to the same spot?", "options": ["It''s required by the rules", "It keeps the returner guessing and prevents them from grooving a return pattern", "It doesn''t matter at all", "Wide serves are illegal on second serve"], "correct": 1, "explain": "Varying placement (T, body, wide) — a serve-variety skill 3.5 players are expected to be developing — stops the returner from anticipating and grooving their return, giving you more free or easy points."}, {"q": "You just won 4 points in a row and have real momentum. What''s a smart mindset?", "options": ["Assume you''ll win easily and relax completely", "Stay focused on your routine and keep executing the same game plan that''s working", "Try something totally new to end it faster", "Start talking trash to your opponent"], "correct": 1, "explain": "Momentum is best protected by sticking with what''s working and staying disciplined — not by relaxing or changing everything."}, {"q": "Your opponent just won several points in a row and has momentum. What can help you most?", "options": ["Panic and rush your next serve", "Use your reset routine, slow the pace between points (within the rules), and refocus on your game plan", "Copy exactly what they''re doing", "Give up on your patterns"], "correct": 1, "explain": "A calm reset routine and returning to your own reliable patterns is the best way to stop an opponent''s momentum."}, {"q": "In a tiebreak, why is it important to know whose turn it is to serve and the score at all times?", "options": ["It isn''t important", "Because tiebreaks are short, and one lapse in focus on serve/score can cost several points quickly", "Only the umpire needs to know", "Because you get bonus points for knowing"], "correct": 1, "explain": "Tiebreaks are short and every point matters more — staying sharp on serve rotation and score keeps you from wasting easy points."}, {"q": "You''re facing a strong second-serve return opportunity (the serve is a weak, slow second serve). What should you do?", "options": ["Play it safe and just get it back in the middle", "Step in and attack it aggressively, since a weak second serve is a chance to take control", "Let it bounce twice", "Return it exactly the same as you would a first serve out wide"], "correct": 1, "explain": "A weak second serve is a tactical opportunity — stepping in and attacking it can win you the point outright or force a weak reply."}, {"q": "Late in a long match, your technique starts to break down from fatigue. What''s the priority?", "options": ["Try new, riskier shots since you''re tired anyway", "Simplify — rely on your most reliable, well-grooved shots and shorten points when you can", "Slow your footwork down on purpose", "Stop using your mental routine"], "correct": 1, "explain": "When fatigued, simplifying to your most reliable patterns protects your level better than experimenting."}, {"q": "What is a ''peak performance routine'' meant to do before a big match?", "options": ["Guarantee a win", "Get your body and mind into a consistent, focused, ready state using familiar warm-up and mental steps", "Make you nervous on purpose", "Replace physical warm-up entirely"], "correct": 1, "explain": "A peak performance routine (physical warm-up + mental steps) helps you arrive at the first point ready and focused, not rushed or flat."}, {"q": "Why is scouting an opponent''s patterns (if you get the chance) useful before a match?", "options": ["It''s not useful — every opponent should be treated the same", "It helps you form a simple, specific game plan (e.g., attack their weaker side, expect certain patterns)", "It''s against the rules", "It guarantees you won''t need any tactics"], "correct": 1, "explain": "Knowing tendencies (favorite patterns, weaker side, style of play) lets you build a more specific, effective game plan."}, {"q": "You disguise your serve toss and motion so it looks the same for a kick serve or a flat serve out wide. Why is this useful?", "options": ["It isn''t — disguise doesn''t matter in serving", "It prevents the returner from reading your serve early and getting a head start", "It''s required for a legal serve", "It only matters in doubles"], "correct": 1, "explain": "Disguise delays the returner''s read, giving you a timing advantage even on a serve they eventually identify correctly."}, {"q": "At the end of a long, successful year of training, what''s a healthy next step?", "options": ["Immediately start over with beginner basics", "Reflect on progress, review goals, and set new, appropriately challenging goals for the next season", "Stop playing tennis for a full year", "Assume no more improvement is possible"], "correct": 1, "explain": "A season-end review — celebrating progress and setting fresh, appropriately challenging goals — keeps development moving in the right direction."}]'::jsonb),
  ('youth', null, null, 'red_starter', 1, '[{"q": "You''re waiting for the ball to come to you. What should your feet do?", "options": ["Stand still and flat-footed", "Stay bouncy and ready to move, like a frog about to jump"], "correct": 1, "explain": "Bouncy, ready feet let you move fast in any direction!"}, {"q": "A balloon is floating toward you. What''s the move?", "options": ["Let it fall to the ground", "Give it a gentle tap to keep it up"], "correct": 1, "explain": "Keeping the balloon up practices watching the ball all the way to your racquet."}, {"q": "Your coach rolls a ball to you. What''s the best way to pick it up with your racquet?", "options": ["Scoop it up with the racquet face", "Kick it away"], "correct": 0, "explain": "Scooping with the racquet face is great practice for soft hands."}]'::jsonb),
  ('youth', null, null, 'red_rally', 2, '[{"q": "The ball bounces on your left side, and you''re building toward NTRP 2.5 rallies. Which shot do most right-handed players use?", "options": ["Forehand", "Backhand"], "correct": 1, "explain": "A ball on your non-racquet-hand side is usually your backhand — getting comfortable with it on both sides is part of the 2.5 track."}, {"q": "You need to move sideways to reach a ball. What should your feet do?", "options": ["Cross your feet over each other", "Shuffle sideways, feet apart"], "correct": 1, "explain": "Shuffling keeps you balanced and ready to change direction."}, {"q": "You just hit your serve. What''s next?", "options": ["Get ready to play the next shot", "Sit down and relax"], "correct": 0, "explain": "The point isn''t over after your serve — stay ready!"}]'::jsonb),
  ('youth', null, null, 'red_game_player', 3, '[{"q": "The ball bounces twice before you hit it. What happens?", "options": ["You can still hit it", "The point is over"], "correct": 1, "explain": "Two bounces means the point is over — that''s the two-bounce rule."}, {"q": "After you hit the ball, where''s the best place to go?", "options": ["Stay exactly where you are", "Move back to the middle of your side"], "correct": 1, "explain": "Moving back to the middle helps you reach the next ball, wherever it goes."}, {"q": "Your partner misses an easy shot in a doubles game. What''s a good thing to say?", "options": ["\"That''s okay — get the next one!\"", "Nothing, just ignore them"], "correct": 0, "explain": "Good teammates encourage each other, especially after a miss."}]'::jsonb),
  ('youth', null, null, 'orange_ready', 4, '[{"q": "The ball bounces short, close to the net. What should you do?", "options": ["Move up and hit it", "Stay back at the baseline"], "correct": 0, "explain": "A short ball is your chance to move in and take charge of the point — at the 2.5 level this should be an automatic reaction, not a guess."}, {"q": "The ball bounces deep, near the baseline. What should you do?", "options": ["Move up close to the net", "Stay back and give yourself room"], "correct": 1, "explain": "A deep ball needs room to swing — staying back gives you time, and reading short-vs-deep quickly is a 2.5-level skill."}, {"q": "Before your first real mini-tournament match at the 2.5 level, what''s a great habit?", "options": ["Shake hands and say \"good luck!\"", "Ignore your opponent completely"], "correct": 0, "explain": "Good sportsmanship starts before the first point is even played."}]'::jsonb);
